  if(!admin)tasks.push(['shared',supabase.rpc('pl2_shared_results')],['sharedGroupFeedback',supabase.rpc('pl2_shared_group_feedback')],['myAudit',supabase.rpc('pl2_my_audit')]);
  if(admin)tasks.push(['moderations',supabase.from('moderations').select('*')],['profiles',supabase.from('profiles').select('*')],['audit',supabase.from('audit_logs').select('*').order('occurred_at',{ascending:false}).limit(150)],['groupFeedback',supabase.from('group_feedback').select('*')],['individualFeedback',supabase.from('individual_feedback').select('*')]);
  const responses=await Promise.all(tasks.map(async ([key,q])=>({key,...await q})));
