 const finished=computed.filter(x=>x.computed.status==='complete');const adminD=computed.filter(x=>x.computed.status==='administrative');const pending=computed.filter(x=>!['complete','administrative'].includes(x.computed.status));const scored=computed.filter(x=>x.computed.preliminary&&!['administrative','exception','duplicate'].includes(x.computed.status));const avg=scored.length?round2(scored.reduce((n,x)=>n+x.computed.preliminary.value,0)/scored.length):null;
