 <div className="section-between"><div><span className="eyebrow">RINGKASAN PROGRES</span><h2>{admin?'Snapshot penilaian seluruh peserta':'Monitoring realtime seluruh jabatan (baca-saja)'}</h2></div><span className="live-label"><span className="live-dot"/> Data sinkron realtime</span></div>
